/**
 * Pre-step processing for a dynamic body.
 *
 * Processes input controls and calculates forces to apply in the
 * physics step. Handles various camera modes and movement styles.
 *
 * **Processing Order**
 *
 * 1. Camera mode-specific rotation
 * 2. Force calculation from input axes
 * 3. Drift bonus application (for driving)
 * 4. Gravity bonus calculation
 *
 * **Input Channels**
 *
 * | Input | Purpose |
 * |-------|---------|
 * | xAxisCtrl | Strafe/turn left-right (-1 to 1) |
 * | yAxisCtrl | Move forward-back (-1 to 1) |
 * | xAxisMouseCtrl | Mouse/look rotation |
 *
 * @param {Object} body - Physics body instance
 * @param {THREE.Object3D} body.transformer - Position/rotation container
 * @param {boolean} body.controlsLocked - Whether controls are disabled
 * @param {THREE.Quaternion} body.lastTurn - Previous frame turn quaternion
 * @param {number} fixedTimestep - Fixed timestep in seconds (e.g., 1/60)
 * @param {BufferBackedObject} sDynamic - Shared buffer view for this body
 * @param {number} index - Body index in the dynamic bodies array
 *
 * @example
 * ```javascript
 * // Called at the start of each physics step
 * for ( let i = 0; i < dynamicBodies.length; i++ ) {
 *   const body = dynamicBodies[i];
 *   const shared = sharedDynamic[i];
 *   if ( shared.used ) {
 *     preStep( body, FIXED_TIMESTEP, shared, i );
 *     dynamic( body, FIXED_TIMESTEP, shared, i );
 *   }
 * }
 * ```
 */
export function preStep(body: {
    transformer: THREE.Object3D;
    controlsLocked: boolean;
    lastTurn: THREE.Quaternion;
}, fixedTimestep: number, sDynamic: BufferBackedObject, _index: any): void;
export const up: any;
